        from typing import Literal, Dict, Optional, List, Union
        def safe_convert_dtype(series: pd.Series, dtype: Union[str, type], sample: int = 10) -> pd.Series:
            bad_rows = []
            results = []

            for idx, val in series.items():
                try:
                    if pd.isna(val):
                        results.append(pd.NA)
                    elif str(dtype).startswith("datetime"):
                        results.append(pd.to_datetime(val))
                    else:
                        results.append(pd.Series([val]).astype(dtype).iloc[0])
                except Exception as e:
                    bad_rows.append((idx, val, str(e)))
                    results.append(pd.NA)

            if bad_rows:
                bad_vals = pd.Series([v for _, v, _ in bad_rows], dtype="object")
                vc = bad_vals.value_counts(dropna=False).head(sample)
                idx_preview = [i for i, _, _ in bad_rows[:sample]]
                err_preview = " ".join(f"Row {i}: {repr(v)}" for i, v, _ in bad_rows[:sample])

                raise ValueError(
                    f"Failed converting Series '{series.name}' to dtype {dtype!r} due to {len(bad_rows)} failed cases, such as \n"
                    f"{err_preview}"
                )

            return pd.Series(results, index=series.index, name=series.name)

        df[new_col] = safe_convert_dtype(df[column],replace_type)

    else:
        raise ValueError(f"Unsupported operation: {operation}")


